begin;
create extension if not exists pgtap with schema extensions;
select extensions.no_plan();
select extensions.ok(not has_function_privilege('anon','public.find_project_request(text)','execute'),'anonymous cannot search private references');
select extensions.ok(not has_function_privilege('service_role','public.find_project_request(text)','execute'),'ingress secret has no staff search grant');
select extensions.ok(not has_function_privilege('anon','public.list_request_attachments(uuid)','execute'),'anonymous cannot list attachments');
select extensions.ok((select prosecdef and proconfig @> array['search_path=""'] from pg_proc where oid='public.find_project_request(text)'::regprocedure),'search function definer uses empty search path');
insert into auth.users(id) values('49000000-0000-4000-8000-000000000001');
insert into auth.mfa_factors(id,user_id,factor_type,status,created_at,updated_at) values('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001','totp','verified',now(),now());
insert into auth.sessions(id,user_id,factor_id,aal) values('49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001','49000000-0000-4000-8000-000000000001','aal2');
insert into public.team_profiles(id,full_name) values('49000000-0000-4000-8000-000000000001','Local management test');
insert into public.team_role_assignments select '49000000-0000-4000-8000-000000000001',id from public.roles where code='operations_lead';
insert into public.services(id,slug,title,description,status,accepting_requests) values('49100000-0000-4000-8000-000000000001','management-fixture','Test fixture','Test description','published',true);
insert into public.service_budget_options(id,service_id,label,is_unsure) values('49200000-0000-4000-8000-000000000001','49100000-0000-4000-8000-000000000001','Not sure yet',true);
insert into business_private.project_requests(id,reference,service_id,service_snapshot,full_name,email,whatsapp,requirements,consent_version,idempotency_hash,payload_hash)
 values('49300000-0000-4000-8000-000000000001','BWR-49000000000040008000000000000001','49100000-0000-4000-8000-000000000001','{"title":"Test snapshot"}','Local Client','management@example.invalid','+237600000000','Synthetic request for testing only','test',decode(repeat('49',32),'hex'),decode(repeat('48',32),'hex'));
insert into business_private.request_attachments(id,request_id,object_key,display_name,mime_type,byte_size,sha256_hex) values('49400000-0000-4000-8000-000000000001','49300000-0000-4000-8000-000000000001','49300000-0000-4000-8000-000000000001/49400000-0000-4000-8000-000000000001','test.pdf','application/pdf',100,repeat('a',64));
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","session_id":"49000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal1","exp":4102444800}',true);
select extensions.throws_ok($$select public.find_project_request('BWR-49000000000040008000000000000001')$$,'42501',null,'AAL1 reference search denied');
select extensions.throws_ok($$select public.list_request_attachments('49300000-0000-4000-8000-000000000001')$$,'42501',null,'AAL1 metadata denied');
select set_config('request.jwt.claims','{"sub":"49000000-0000-4000-8000-000000000001","session_id":"49000000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2","exp":4102444800}',true);
select extensions.is(jsonb_array_length(public.find_project_request('BWR-49000000000040008000000000000001')),1,'authorized exact reference found');
select extensions.is(jsonb_array_length(public.find_project_request('BWR-00000000000000000000000000000000')),0,'unknown reference empty');
select extensions.throws_ok($$select public.find_project_request('%')$$,'22023',null,'wildcard searches denied');
select extensions.is(public.list_request_attachments('49300000-0000-4000-8000-000000000001')->0->>'scan_status','quarantined','authorized metadata reports quarantine');
select extensions.ok(not(public.list_request_attachments('49300000-0000-4000-8000-000000000001')->0 ? 'object_key'),'no private object key in metadata');
select extensions.throws_ok($$select public.save_service_budget('49200000-0000-4000-8000-000000000001',1,'49100000-0000-4000-8000-000000000001','Not sure yet','XAF',null,null,true,false,10)$$,'22023',null,'last active uncertainty choice cannot be disabled');
reset role;
update public.team_profiles set is_active=false where id='49000000-0000-4000-8000-000000000001';
set local role authenticated;
select extensions.throws_ok($$select public.find_project_request('BWR-49000000000040008000000000000001')$$,'42501',null,'inactive staff search denied');
select extensions.throws_ok($$select public.list_request_attachments('49300000-0000-4000-8000-000000000001')$$,'42501',null,'inactive staff metadata denied');
reset role;
select * from extensions.finish();
rollback;
